{
  "purpose": "只审两项新桥接是否可执行：古境值守/返宗/437日双岗看押，六号箱失踪/证据/药物数量/责任；不是后两卷整体评审，不要求先写正文，不把旧历史越阶事实混入新提案。第一卷相关章纲作相互校验，三卷宏观其余部分仍未批准。",
  "base": {
    "world": 19,
    "bible": 29,
    "plan": 28,
    "planId": "plan_2a5a36c370184892bd2f7e7ec248bcab"
  }
}

{
  "status": "proposed_not_adopted",
  "roles": {
    "gate": "太清本批名册仍有人在古境期间的接待与护送岗位；全员退出并销班后可撤桌，不代表关闭或遗弃整个三方古境。",
    "custody": "任何时候至少一名实际在场的玄府负责墨，不用凡绳宣称永久封禁。"
  },
  "movements": [
    {
      "day": 60,
      "where": "loc_29",
      "people": [
        "char_10",
        "char_12",
        "char_13"
      ],
      "event": "顾说明原先已排的后半期轮换：褚衡、邵闻第186日从外门出发，188日暮到外营，189日交班。抽调邵减少一条外山晚巡，褚的一段例行巡检延期；尚不知道会擒获墨。顾当日寿储下界至少12。"
    },
    {
      "day": 180,
      "where": "loc_29",
      "people": [
        "char_17",
        "char_18"
      ],
      "event": "二人核对186出发的行粮、执事牌和换班期，拒绝提前同行帮主角争泉；本批太清预计211日前结束，伤病则延后销班。"
    },
    {
      "fromDay": 186,
      "toDay": 188,
      "where": "loc_04→loc_05外营",
      "people": [
        "char_17",
        "char_18"
      ],
      "event": "沿与首批同一山路行三日，188日暮到达入口外营；25章战斗已结束，不倒填他们援助顾擒墨。"
    },
    {
      "day": 189,
      "where": "loc_05外营",
      "people": [
        "char_12",
        "char_13",
        "char_17",
        "char_18"
      ],
      "event": "乔辰初向顾接墨。189起杜/褚轮入口、乔/邵轮看押；每人12小时当值12小时休息。入口与囚棚各一人，顾疗伤不计入值班容量。"
    },
    {
      "fromDay": 203,
      "toDay": 211,
      "where": "loc_05外营",
      "people": [
        "char_10"
      ],
      "event": "顾复诊只准每日最多2小时入口轻值，具体面交前由杜或褚继续负责；短班只给该值守额外休息，不代替四人基础轮班。"
    },
    {
      "day": 212,
      "where": "loc_05外营",
      "people": [
        "char_02",
        "char_09",
        "char_10",
        "char_12",
        "char_13",
        "char_17",
        "char_18"
      ],
      "event": "林随车已离开后，剩余采集者逐名退出，杜褚对全部太清本批名册点验，签本批销班；发现缺人则延后返程。白榆批准伤者坐车，顾不承担擒敌值守。"
    },
    {
      "fromDay": 213,
      "toDay": 216,
      "where": "loc_05外营→loc_29",
      "people": [
        "char_02",
        "char_04",
        "char_09",
        "char_10",
        "char_12",
        "char_13",
        "char_17",
        "char_18"
      ],
      "event": "按有伤者的慢车四日返外门。乔和邵分昼夜各12小时近身看墨，另一人随队车休息；杜褚分别护前后路、轮换休息，苏护证，白榆顾随医车。无未交接离岗、无人把睡眠记作继续看押。"
    },
    {
      "fromDay": 216,
      "toDay": 436,
      "where": "loc_29值守房",
      "people": [
        "char_12",
        "char_13",
        "char_17",
        "char_18"
      ],
      "event": "四名玄府轮一处羁押岗，每人6小时；其余时间休息或在不重叠的时段执行宗门事务。墨就医或移房由休班者提前面交增援，缩减外山例行巡检并记加班俸，不使用自创封禁。顾康复后指导林修行，不在此班表里重复计数。"
    },
    {
      "fromDay": 437,
      "toDay": 466,
      "where": "loc_29两间值守房",
      "people": [
        "char_12",
        "char_13",
        "char_17",
        "char_18"
      ],
      "event": "邵辰初当面接顾交来的伤押卫，乔仍看墨。此后墨岗乔日/杜夜，伤押卫岗邵日/褚夜，均12小时值12小时休，暂停四人其他外出差事。顾签完交接才就医；若需就医加押，先调用休班者并顺延其下一班，缺员即停止移送，不宣称普通绳索永久拘禁。"
    }
  ],
  "guLife": {
    "baselineDay": 60,
    "lowerBound": 12,
    "casts": [
      {
        "day": 188,
        "cost": 0.25
      },
      {
        "day": 436,
        "cost": 0.25
      }
    ],
    "balance436": 10.46986301369863,
    "note": "原章15的基线是第60日，不是第180日；不靠重新诊断制造120日寿元。"
  }
}

{
  "status": "proposed_not_adopted",
  "contents": {
    "box6Original": 24,
    "unit": "包普通低阶草药",
    "recovered": 12,
    "burned": 6,
    "soldAndUsed": 6,
    "total": 24
  },
  "timeline": [
    {
      "day": 214,
      "event": "实际装箱清单列六号箱24包普通药材，31章港验与清单一致。"
    },
    {
      "day": 215,
      "event": "严涛想私卖抵赌债，私推六号箱到侧舱时夹伤脚；林忙救人。严叫水手常钧把该箱搬去普通备缆间避浪，常不知偷卖意图，亲自留暂存粉板记号。严之后涂掉记号，林清点本货舱只见五箱，未获全船搜查权。"
    },
    {
      "day": 216,
      "event": "靠港后第六箱仍在备缆间，不是海上被高阶术法送走；林尚未知道。"
    },
    {
      "day": 217,
      "event": "严以旧识找陆沉舟弟弟，把箱从备缆间经普通卸货侧门交程记；陆弟按程记便条领走，常帮抬至码头但不跟去仓。严实收私卖款，借脚伤不下船查验；程暂不来正式接五箱。"
    },
    {
      "fromDay": 218,
      "toDay": 223,
      "event": "程记医铺售出其中6包已用于普通伤病，留有对应散卖页；12包带原批签存后架，6包留前柜。不能把24包重新算成无数箱禁药或高品火髓。"
    },
    {
      "day": 225,
      "event": "第37章程记仓火，前柜6包焚毁。林先救陆弟，水手与贺从仓边搬出后架带原批签12包；主角手受伤不搬重物。箱外板刻号与绳孔吻合，能够认出处而不能自动证明海上经过。"
    },
    {
      "fromDay": 227,
      "toDay": 230,
      "event": "38章常当面指备缆间、涂板与卸货门，严在其证言和陆弟领货便条前承认私挪；39章对12包实物、已售6包账与烧损6包实地核账。原船主收回12包；6包已用于病人不追讨患者，其余损失向实际偷卖/收赃者追偿，未实收到赔款不记收入。"
    }
  ],
  "knowledge": [
    {
      "chapter": 33,
      "linKnows": "从船册确认被救押货者姓名严涛；失箱仍未知。"
    },
    {
      "chapter": 35,
      "linKnows": "常指认曾按严口令搬箱到备缆间，仅证实搬移动作，仍不知道药材归属。"
    },
    {
      "chapter": 37,
      "linKnows": "火场取到外板与12包原签药，知道箱到过程记。"
    },
    {
      "chapter": 38,
      "linKnows": "严承认私挪、常复述实搬路径，陆弟便条与二人签认交叉核对。"
    },
    {
      "chapter": 39,
      "linKnows": "24包分成12回收/6烧损/6已售用；海上私挪与到港交货可以复核，不等于已经证明赵指使仓火或九鼎全网。"
    }
  ],
  "liability": "林失去既定履约奖金和复验费，不把救人的选择写成偷卖同谋；原船主承认其有权在未获准的情况下不搜备缆间，不追加全箱赔债。严、收赃方及船主各承担可证责任，追偿未收不填成收入。",
  "payoff": "第39章查清本箱去向与责任分配，本线可在后续实际章节验收后收束；第100章无需仍把箱板当无解谜题。"
}

